// Simple README story diagrams (few big boxes, almost no text). Same palette as build.mjs; no legend on purpose.
// Generated by `pnpm diagrams` (render.mjs imports this after build.mjs). Facts: docs/devkitv1/writeup/tx.md.
import { fileURLToPath } from 'node:url'
import { scene, FILL, MUTED } from './build.mjs'

const dir = fileURLToPath(new URL('./', import.meta.url))

function kit(s) {
  return {
    box(x, y, w, h, text, layer, { fs = 26, kind = 'step', sub } = {}) {
      s.shape(kind, x, y, w, h, { fill: FILL[layer] })
      const lines = text.split('\n').length
      const th = lines * fs * 1.25 + (sub ? 24 : 0)
      s.text(x + 6, y + (h - th) / 2, w - 12, text, { fs })
      if (sub) s.text(x + 6, y + (h - th) / 2 + lines * fs * 1.25 + 2, w - 12, sub, { fs: 17, color: MUTED })
    },
    label(x, y, w, text, o = {}) { s.text(x, y, w, text, { fs: 20, color: MUTED, ...o }) },
  }
}

// ---------- story-trick: 2-FSK inside a packet, hopping between packets ----------
{
  const s = scene(), k = kit(s)
  // (a) one packet: carrier toggles between two tones
  const ax = 40, ay = 60, aw = 330, ah = 230
  s.text(ax, -50, aw, 'one packet', { fs: 28 })
  s.arrow([[ax, ay + ah], [ax + aw, ay + ah]]); s.arrow([[ax, ay + ah], [ax, ay]])
  k.label(ax + aw - 80, ay + ah + 8, 80, 'time', { align: 'right' })
  k.label(ax - 30, ay - 34, 120, 'freq', { align: 'left' })
  const hi = ay + 60, lo = ay + 150, bits = [1, 0, 1, 1, 0, 0, 1, 0], bw = 36, x0 = ax + 22
  const pts = []
  bits.forEach((b, i) => { const y = b ? hi : lo; pts.push([x0 + i * bw, y], [x0 + (i + 1) * bw, y]) })
  s.arrow(pts, { head: false, kind: 'ctl', width: 3 })
  bits.forEach((b, i) => s.text(x0 + i * bw, ay + 8, bw, String(b), { fs: 22, color: '#2f9e44' }))
  s.text(ax, ay + ah + 44, aw, 'two tones = bits', { fs: 24 })

  // (b) many packets: each on the next channel of a fixed hop order
  const bx = 470, by = ay, cols = 9, rows = 10, cw = 38, rh = ah / rows
  s.text(bx, -50, cols * cw + 20, 'many packets', { fs: 28 })
  s.arrow([[bx, by + ah], [bx + cols * cw + 24, by + ah]]); s.arrow([[bx, by + ah], [bx, by]])
  k.label(bx + cols * cw - 60, by + ah + 8, 84, 'time', { align: 'right' })
  k.label(bx - 30, by - 34, 200, '47 channels', { align: 'left' })
  for (let r = 1; r < rows; r++) s.arrow([[bx + 4, by + r * rh], [bx + cols * cw + 10, by + r * rh]], { head: false, width: 1 })
  s.els.slice(-(rows - 1)).forEach((e) => { e.strokeColor = '#dee2e6'; e.strokeStyle = 'dotted' })
  const hop = [2, 7, 4, 9, 1, 6, 3, 8, 5].map((r) => rows - r)
  const centres = hop.map((r, c) => [bx + 20 + c * cw, by + (r - 0.5) * rh])
  s.arrow(centres, { head: false, width: 1 }); s.els.at(-1).strokeColor = '#adb5bd'; s.els.at(-1).strokeStyle = 'dashed'
  for (const [cx, cy] of centres) s.shape('phys', cx - 9, cy - 9, 18, 18, { fill: FILL.rf })
  s.text(bx - 20, by + ah + 44, cols * cw + 60, 'next channel every 9 ms', { fs: 24 })
  s.save(dir + 'story-trick.excalidraw')
}

// ---------- story-steal: copy the E8's identity into the ESP32 ----------
{
  const s = scene(), k = kit(s)
  const y = 40, h = 110, w = 200, gap = 120
  const X = [0, w + gap, 2 * (w + gap)]
  k.box(X[0], y, w, h, 'E8 radio', 'mech')
  k.box(X[1], y, w, h, 'drone', 'fw', { sub: 'Betaflight config' })
  k.box(X[2], y, w, h, 'ESP32', 'fw')
  s.arrow([[X[0] + w + 6, y + h / 2], [X[1] - 6, y + h / 2]]); k.label(X[0] + w, y + h / 2 - 34, gap, 'bind')
  s.arrow([[X[1] + w + 6, y + h / 2], [X[2] - 6, y + h / 2]], { kind: 'usb' }); k.label(X[1] + w, y + h / 2 - 60, gap, 'copy\nover USB', { color: '#6741d9' })
  // what is copied
  k.box(X[1] + 20, y + h + 50, w - 40, 56, 'ID + hops', 'dig', { kind: 'data', fs: 22 })
  s.arrow([[X[1] + w / 2, y + h + 4], [X[1] + w / 2, y + h + 46]], { head: false, width: 1 })
  s.text(X[2] - 10, y + h + 30, w + 20, 'now sends\nas the E8', { fs: 24, color: '#2f9e44' })
  s.save(dir + 'story-steal.excalidraw')
}

// ---------- story-testloop: the bench loop ----------
{
  const s = scene(), k = kit(s)
  const w = 200, h = 100, gap = 130, y = 40
  const X = [0, w + gap, 2 * (w + gap)]
  k.box(X[0], y, w, h, 'laptop', 'app')
  k.box(X[1], y, w, h, 'ESP32', 'fw', { sub: 'TX firmware' })
  k.box(X[2], y, w, h, 'Tinyhawk', 'fw', { sub: 'test receiver' })
  s.arrow([[X[0] + w + 6, y + h / 2], [X[1] - 6, y + h / 2]]); k.label(X[0] + w, y + h / 2 - 34, gap, 'USB')
  s.arrow([[X[1] + w + 6, y + h / 2], [X[2] - 6, y + h / 2]]); k.label(X[1] + w, y + h / 2 - 34, gap, '2.4 GHz', { color: '#c92a2a' })
  // receiver reports back to the laptop over USB (logs)
  const yb = y + h + 190
  s.arrow([[X[2] + w / 2, y + h + 6], [X[2] + w / 2, yb], [X[0] + w / 2, yb], [X[0] + w / 2, y + h + 6]], { kind: 'tlm' })
  k.label(X[1], yb + 6, w, 'USB: logs')
  // loop: change firmware, try again
  const cx = X[1] - 10, cy = (y + h + yb) / 2, r = 50
  const loop = []
  for (let a = 20; a <= 320; a += 15) loop.push([cx + r * Math.cos(a * Math.PI / 180), cy + r * Math.sin(a * Math.PI / 180)])
  s.arrow(loop, { width: 2 }); s.els.at(-1).roundness = { type: 2 }; s.els.at(-1).strokeColor = '#2f9e44'; s.els.at(-1).endArrowhead = 'triangle'
  s.text(cx + r + 24, cy - 32, 360, 'change firmware,\ntry again', { fs: 26, color: '#2f9e44', align: 'left' })
  s.save(dir + 'story-testloop.excalidraw')
}

// ---------- story-final: what the user ends up with ----------
{
  const s = scene(), k = kit(s)
  const w = 190, h = 100, gap = 110, y = 40
  const X = [0, 1, 2].map((i) => i * (w + gap))
  k.box(X[0], y, w, h, 'browser tab', 'app')
  k.box(X[1], y, w, h, 'ESP32', 'fw')
  k.box(X[2], y, w, h, 'drone', 'mech')
  const cy = y + h / 2
  s.arrow([[X[0] + w + 6, cy - 12], [X[1] - 6, cy - 12]]); k.label(X[0] + w, cy - 46, gap, 'USB')
  s.arrow([[X[1] + w + 6, cy - 12], [X[2] - 6, cy - 12]]); k.label(X[1] + w, cy - 46, gap, '2.4 GHz', { color: '#c92a2a' })
  s.arrow([[X[2] - 6, cy + 14], [X[1] + w + 6, cy + 14]], { kind: 'tlm' })
  s.arrow([[X[1] - 6, cy + 14], [X[0] + w + 6, cy + 14]], { kind: 'tlm' })
  k.label(X[1] + w - 20, cy + 26, gap + 40, 'telemetry')
  s.text(X[0] - 10, y + h + 16, w + 20, 'or any program\non the computer', { fs: 18, color: MUTED })
  s.save(dir + 'story-final.excalidraw')
}

export const STORY = ['story-trick', 'story-steal', 'story-testloop', 'story-final']
